"""
hardware.py — system hardware detection for BulwarkOS OOBE.

All reads are from /sys and /proc — no external tools required except
lspci (from pciutils) for human-readable device descriptions.
Designed to be called in a background thread (never on the GTK main loop).
"""

import os
import re
import subprocess
from pathlib import Path

from ..state import DetectedHardware, NICDevice, GPUDevice


# ---------------------------------------------------------------------------
# CPU / IOMMU
# ---------------------------------------------------------------------------

def detect_cpu_vendor() -> tuple[str, str]:
    """
    Returns (vendor, model) where vendor is 'intel' or 'amd'.
    Falls back to 'unknown' if /proc/cpuinfo is unreadable.
    """
    vendor = "unknown"
    model = "Unknown CPU"
    try:
        with open("/proc/cpuinfo") as f:
            for line in f:
                if line.startswith("vendor_id"):
                    raw = line.split(":")[1].strip().lower()
                    if "amd" in raw:
                        vendor = "amd"
                    elif "intel" in raw or "genuineintel" in raw:
                        vendor = "intel"
                elif line.startswith("model name") and model == "Unknown CPU":
                    model = line.split(":")[1].strip()
    except OSError:
        pass
    return vendor, model


def is_iommu_active() -> bool:
    """
    IOMMU is active if /sys/kernel/iommu_groups/ exists and is non-empty.
    This requires that the kernel was booted with intel_iommu=on or amd_iommu=on.
    """
    iommu_path = Path("/sys/kernel/iommu_groups")
    if not iommu_path.exists():
        return False
    try:
        return any(iommu_path.iterdir())
    except PermissionError:
        return False


def count_iommu_groups() -> int:
    iommu_path = Path("/sys/kernel/iommu_groups")
    if not iommu_path.exists():
        return 0
    try:
        return sum(1 for p in iommu_path.iterdir() if p.is_dir())
    except PermissionError:
        return 0


def get_iommu_group_members() -> dict[int, list[str]]:
    """
    Returns {group_id: [pci_address, ...]} for all IOMMU groups.
    PCI addresses in the form '0000:05:00.0'.
    """
    groups: dict[int, list[str]] = {}
    iommu_path = Path("/sys/kernel/iommu_groups")
    if not iommu_path.exists():
        return groups
    for group_dir in iommu_path.iterdir():
        if not group_dir.is_dir():
            continue
        try:
            group_id = int(group_dir.name)
        except ValueError:
            continue
        devices_path = group_dir / "devices"
        if not devices_path.exists():
            continue
        members = []
        for dev_link in devices_path.iterdir():
            pci_addr = dev_link.name
            # Normalise to '0000:xx:xx.x' form
            if re.match(r"[0-9a-f]{4}:[0-9a-f]{2}:[0-9a-f]{2}\.[0-9a-f]", pci_addr):
                members.append(pci_addr)
        groups[group_id] = members
    return groups


def is_secure_boot_enabled() -> bool:
    """Check mokutil / efivar for Secure Boot state."""
    try:
        result = subprocess.run(
            ["mokutil", "--sb-state"],
            capture_output=True, text=True, timeout=3
        )
        return "enabled" in result.stdout.lower()
    except (FileNotFoundError, subprocess.TimeoutExpired):
        pass
    # Fallback: read EFI variable directly
    sb_var = Path("/sys/firmware/efi/efivars/SecureBoot-8be4df61-93ca-11d2-aa0d-00e098032b8c")
    if sb_var.exists():
        try:
            data = sb_var.read_bytes()
            # Last byte: 0x01 = enabled
            return len(data) >= 5 and data[4] == 1
        except OSError:
            pass
    return False


# ---------------------------------------------------------------------------
# PCI device description (lspci)
# ---------------------------------------------------------------------------

def _lspci_descriptions() -> dict[str, str]:
    """
    Runs lspci and returns {pci_address: description}.
    Falls back to empty dict if lspci is not installed.
    """
    desc: dict[str, str] = {}
    try:
        result = subprocess.run(
            ["lspci", "-mm"],
            capture_output=True, text=True, timeout=5
        )
        for line in result.stdout.splitlines():
            parts = line.split('"')
            if len(parts) >= 5:
                addr = parts[0].strip()
                # Normalise short address '05:00.0' → '0000:05:00.0'
                if addr.count(":") == 1:
                    addr = "0000:" + addr
                vendor = parts[3]
                device = parts[5] if len(parts) > 5 else ""
                desc[addr] = f"{vendor} {device}".strip()
    except (FileNotFoundError, subprocess.TimeoutExpired):
        pass
    return desc


def _read_pci_id(pci_address: str, filename: str) -> str:
    """Read a hex value like vendor or device ID from /sys."""
    path = Path(f"/sys/bus/pci/devices/{pci_address}/{filename}")
    try:
        return path.read_text().strip()
    except OSError:
        return "0000"


# ---------------------------------------------------------------------------
# NIC detection
# ---------------------------------------------------------------------------

# PCI class codes that indicate network controllers
_NET_CLASSES = {"0200", "0280"}

def detect_nics(group_members: dict[int, list[str]]) -> list[NICDevice]:
    """
    Returns all physical network interfaces that are viable for VFIO passthrough:
    - Must be a PCI network controller (class 02xx)
    - Must not be a virtual/loopback interface
    """
    descriptions = _lspci_descriptions()

    # Build reverse map: pci_address → group_id
    pci_to_group: dict[str, int] = {}
    for gid, members in group_members.items():
        for addr in members:
            pci_to_group[addr] = gid

    nics: list[NICDevice] = []
    net_path = Path("/sys/class/net")
    if not net_path.exists():
        return nics

    for iface_path in net_path.iterdir():
        iface = iface_path.name
        if iface in ("lo",):
            continue
        # Follow symlink to find PCI device
        device_link = iface_path / "device"
        if not device_link.exists():
            continue
        try:
            resolved = os.path.realpath(device_link)
        except OSError:
            continue
        pci_addr = os.path.basename(resolved)
        # Normalise
        if not re.match(r"[0-9a-f]{4}:[0-9a-f]{2}:[0-9a-f]{2}\.[0-9a-f]", pci_addr):
            continue
        # Check PCI class
        pci_class = _read_pci_id(pci_addr, "class")[2:6].lower()
        if not any(pci_class.startswith(c) for c in _NET_CLASSES):
            continue

        vendor_id = _read_pci_id(pci_addr, "vendor").lstrip("0x")
        device_id = _read_pci_id(pci_addr, "device").lstrip("0x")
        vid_did = f"{vendor_id}:{device_id}"

        group_id = pci_to_group.get(pci_addr, -1)
        group_isolated = group_id >= 0 and len(group_members.get(group_id, [])) == 1

        nics.append(NICDevice(
            iface=iface,
            pci_address=pci_addr,
            vendor_id=vid_did,
            description=descriptions.get(pci_addr, f"Network controller [{vid_did}]"),
            iommu_group=group_id,
            group_isolated=group_isolated,
        ))

    return sorted(nics, key=lambda n: n.iface)


# ---------------------------------------------------------------------------
# GPU detection
# ---------------------------------------------------------------------------

# PCI class codes for display controllers / 3D controllers
_GPU_CLASSES = {"0300", "0301", "0302"}

# Vendor IDs for known GPU manufacturers
_GPU_VENDORS = {"10de": "nvidia", "1002": "amdgpu", "8086": "i915"}

def detect_gpus(group_members: dict[int, list[str]]) -> list[GPUDevice]:
    """
    Returns discrete GPUs suitable for VFIO passthrough.
    Integrated Intel graphics are excluded (same IOMMU group as CPU complex).
    """
    descriptions = _lspci_descriptions()

    pci_to_group: dict[str, int] = {}
    for gid, members in group_members.items():
        for addr in members:
            pci_to_group[addr] = gid

    gpus: list[GPUDevice] = []
    pci_devices_path = Path("/sys/bus/pci/devices")
    if not pci_devices_path.exists():
        return gpus

    for dev_path in pci_devices_path.iterdir():
        pci_addr = dev_path.name
        pci_class = _read_pci_id(pci_addr, "class")[2:6].lower()
        if not any(pci_class.startswith(c) for c in _GPU_CLASSES):
            continue

        vendor_hex = _read_pci_id(pci_addr, "vendor").lstrip("0x").lower()
        device_hex = _read_pci_id(pci_addr, "device").lstrip("0x").lower()
        vid_did = f"{vendor_hex}:{device_hex}"

        # Skip unknown vendors and integrated Intel
        driver_name = _GPU_VENDORS.get(vendor_hex, "")
        if not driver_name:
            continue

        # Intel integrated GPUs share group 0 or a group with many devices
        group_id = pci_to_group.get(pci_addr, -1)
        group_size = len(group_members.get(group_id, []))
        if vendor_hex == "8086" and group_size > 3:
            continue  # Almost certainly integrated graphics

        group_isolated = group_id >= 0 and group_size == 1

        gpus.append(GPUDevice(
            pci_address=pci_addr,
            vendor_id=vid_did,
            description=descriptions.get(pci_addr, f"Display controller [{vid_did}]"),
            iommu_group=group_id,
            group_isolated=group_isolated,
            driver=driver_name,
        ))

    return sorted(gpus, key=lambda g: g.pci_address)


# ---------------------------------------------------------------------------
# Top-level scan — called once from background thread
# ---------------------------------------------------------------------------

def run_hardware_scan() -> tuple[DetectedHardware, list[NICDevice], list[GPUDevice]]:
    """
    Full system scan. Returns (hardware, nics, gpus).
    Safe to call from a GLib thread (no GTK calls inside).
    """
    vendor, model = detect_cpu_vendor()
    iommu_active = is_iommu_active()
    group_members = get_iommu_group_members() if iommu_active else {}
    group_count = len(group_members)
    secure_boot = is_secure_boot_enabled()

    hw = DetectedHardware(
        cpu_vendor=vendor,
        cpu_model=model,
        iommu_groups=group_count,
        iommu_active=iommu_active,
        secure_boot=secure_boot,
    )

    nics = detect_nics(group_members) if iommu_active else []
    gpus = detect_gpus(group_members) if iommu_active else []

    return hw, nics, gpus
